macro_rules! deps {
    () => {
        CFG!();
        DropKind!();
        DropTree!();
        BlockAnd!();
        Scope!();
    };
}

macro_rules! build_scope_drops {
    () => {
        deps!();
        # [doc = " Builds drops for `pop_scope` and `leave_top_scope`."] # [doc = ""] # [doc = " # Parameters"] # [doc = ""] # [doc = " * `unwind_drops`, the drop tree data structure storing what needs to be cleaned up if unwind occurs"] # [doc = " * `scope`, describes the drops that will occur on exiting the scope in regular execution"] # [doc = " * `block`, the block to branch to once drops are complete (assuming no unwind occurs)"] # [doc = " * `unwind_to`, describes the drops that would occur at this point in the code if a"] # [doc = "   panic occurred (a subset of the drops in `scope`, since we sometimes elide StorageDead and other"] # [doc = "   instructions on unwinding)"] # [doc = " * `dropline_to`, describes the drops that would occur at this point in the code if a"] # [doc = "    coroutine drop occurred."] # [doc = " * `storage_dead_on_unwind`, if true, then we should emit `StorageDead` even when unwinding"] # [doc = " * `arg_count`, number of MIR local variables corresponding to fn arguments (used to assert that we don't drop those)"] fn build_scope_drops < 'tcx , F > (cfg : & mut CFG < 'tcx > , unwind_drops : & mut DropTree , coroutine_drops : & mut DropTree , scope : & Scope , block : BasicBlock , unwind_to : DropIdx , dropline_to : Option < DropIdx > , storage_dead_on_unwind : bool , arg_count : usize , is_async_drop : F ,) -> BlockAnd < () > where F : Fn (Local) -> bool , { debug ! ("build_scope_drops({:?} -> {:?}), dropline_to={:?}" , block , scope , dropline_to) ; let mut unwind_to = unwind_to ; let mut block = block ; let mut dropline_to = dropline_to ; for drop_data in scope . drops . iter () . rev () { let source_info = drop_data . source_info ; let local = drop_data . local ; match drop_data . kind { DropKind :: Value => { debug_assert_eq ! (unwind_drops . drop_nodes [unwind_to] . data . local , drop_data . local) ; debug_assert_eq ! (unwind_drops . drop_nodes [unwind_to] . data . kind , drop_data . kind) ; unwind_to = unwind_drops . drop_nodes [unwind_to] . next ; if let Some (idx) = dropline_to { debug_assert_eq ! (coroutine_drops . drop_nodes [idx] . data . local , drop_data . local) ; debug_assert_eq ! (coroutine_drops . drop_nodes [idx] . data . kind , drop_data . kind) ; dropline_to = Some (coroutine_drops . drop_nodes [idx] . next) ; } if scope . moved_locals . contains (& local) { continue ; } unwind_drops . add_entry_point (block , unwind_to) ; if let Some (to) = dropline_to && is_async_drop (local) { coroutine_drops . add_entry_point (block , to) ; } let next = cfg . start_new_block () ; cfg . terminate (block , source_info , TerminatorKind :: Drop { place : local . into () , target : next , unwind : UnwindAction :: Continue , replace : false , drop : None , async_fut : None , } ,) ; block = next ; } DropKind :: ForLint (reason) => { if storage_dead_on_unwind { debug_assert_eq ! (unwind_drops . drop_nodes [unwind_to] . data . local , drop_data . local) ; debug_assert_eq ! (unwind_drops . drop_nodes [unwind_to] . data . kind , drop_data . kind) ; unwind_to = unwind_drops . drop_nodes [unwind_to] . next ; } if scope . moved_locals . contains (& local) { continue ; } cfg . push (block , Statement :: new (source_info , StatementKind :: BackwardIncompatibleDropHint { place : Box :: new (local . into ()) , reason , } ,) ,) ; } DropKind :: Storage => { if storage_dead_on_unwind { debug_assert_eq ! (unwind_drops . drop_nodes [unwind_to] . data . local , drop_data . local) ; debug_assert_eq ! (unwind_drops . drop_nodes [unwind_to] . data . kind , drop_data . kind) ; unwind_to = unwind_drops . drop_nodes [unwind_to] . next ; } if let Some (idx) = dropline_to { debug_assert_eq ! (coroutine_drops . drop_nodes [idx] . data . local , drop_data . local) ; debug_assert_eq ! (coroutine_drops . drop_nodes [idx] . data . kind , drop_data . kind) ; dropline_to = Some (coroutine_drops . drop_nodes [idx] . next) ; } assert ! (local . index () > arg_count) ; cfg . push (block , Statement :: new (source_info , StatementKind :: StorageDead (local))) ; } } } block . unit () }
    };
}

build_scope_drops!();